const source=$('Code — Pack tracked threads').first().json||{};
const outreach=source.outreachRows||[];
const playlist=source.playlistRows||[];
const clean=v=>String(v??'').replace(/\s+/g,' ').trim();
const time=v=>{const n=Number(v);if(Number.isFinite(n)&&n>1e11)return n;const d=new Date(v||0).getTime();return Number.isFinite(d)?d:0};
const emailFrom=v=>{const s=clean(v);const m=s.match(/<([^>]+)>/);return clean(m?m[1]:(s.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)||[''])[0]).toLowerCase()};
const displayFrom=v=>{const s=clean(v);return clean(s.replace(/<[^>]+>/,'').replace(/^['\"]|['\"]$/g,''))};
const getThread=m=>clean(m.threadId||m.thread_id||m.Thread_ID);
const getId=m=>clean(m.id||m.messageId||m.message_id);
const getSubject=m=>clean(m.Subject||m.subject);
const getBody=m=>clean(m.textPlain||m.text||m.body||m.snippet||'').slice(0,4000);
const getFrom=m=>clean(m.From||m.from||m.sender||m.fromEmail||'');

// Keep only the bounded fields used below. Never clone the complete Gmail payload.
const latest=new Map();
for(const item of $input.all()){
  const m=item.json||{};const tid=getThread(m);if(!tid)continue;
  const ts=time(m.internalDate||m.date||m.email_ts||m.receivedAt);
  const prev=latest.get(tid);if(prev&&ts<prev.ts)continue;
  latest.set(tid,{tid,ts,id:getId(m),subject:getSubject(m),body:getBody(m),from:getFrom(m)});
}

const tracked=new Map();
for(const r of outreach){const tid=clean(r.Gmail_Thread_ID);if(tid)tracked.set(tid,{kind:'OUTREACH',id:clean(r.Record_ID),sentAt:time(r.Sent_At),subject:clean(r.Subject),recipient:clean(r.Email_To),track:clean(r.Track_URL),outlet:clean(r.Medium||r.Contact_Name),language:clean(r.Language),error:clean(r.Error)});}
for(const r of playlist){const tid=clean(r.Thread_ID);if(tid)tracked.set(tid,{kind:'PLAYLIST',id:clean(r.Log_ID),sentAt:time(r.Sent_At),subject:clean(r.Subject),recipient:clean(r.Recipient),track:clean(r.Track_Name),outlet:clean(r.Source_Name||r.Playlist_Name),language:'',error:clean(r.Error)});}

const paidTerms=/(submission fee|admin fee|paid (?:submission|placement|listing|trial|campaign)|payment|paypal|invoice|pricing|price|charge|campaign package|promotion package|sponsored placement|listing fee|placement fee|we charge|costs?\b|fee\b|opłat|płatn|cennik|koszt|pakiet promocyjny|płatna publikacja|płatne zgłoszenie)/i;
const amount=/(?:\$|€|£)\s?\d+(?:[.,]\d+)?|\d+(?:[.,]\d+)?\s?(?:USD|EUR|GBP|PLN|zł|\$|€|£)/i;
const explicitFree=/(free of charge|no fee|we don'?t charge|without payment|bez opłat|bezpłatn(?:e|a|y|ie)|nie pobieramy opłat)/i;
const hardNoFree=/(best i can do|not feasible.{0,50}free|cannot offer.{0,40}free|can'?t offer.{0,40}free|don'?t offer.{0,40}free|no free trial|free trials?.{0,30}(?:not|isn'?t|wouldn'?t)|only paid|paid trial|nie możemy.{0,40}bezpłat|nie oferujemy.{0,40}darmo|wyłącznie płatn)/i;

const out=[];
for(const [tid,m] of latest){
  const t=tracked.get(tid);if(!t||!m.id)continue;
  if(t.sentAt&&m.ts&&m.ts<=t.sentAt)continue;
  if(t.error.includes(`NEGOTIATION_MSG:${m.id}`))continue;
  const subject=m.subject||t.subject;const probe=`${subject}\n${m.body}`;
  const paid=(paidTerms.test(probe)||amount.test(probe))&&!(explicitFree.test(probe)&&!amount.test(probe)&&!hardNoFree.test(probe));
  if(!paid)continue;
  const recipient=emailFrom(m.from)||emailFrom(t.recipient);if(!recipient||recipient==='virya.crew@gmail.com')continue;
  const previousRounds=(t.error.match(/NEGOTIATION_MSG:/g)||[]).length;
  const round=(hardNoFree.test(probe)||previousRounds>0)?'FINAL':'FIRST';
  const lang=(t.language.toUpperCase()==='PL'||/[ąćęłńóśźż]/i.test(m.body)||/\b(cześć|dzień dobry|opłata|płatn|zł)\b/i.test(m.body))?'PL':'EN';
  const snippets=m.body.split(/(?<=[.!?])\s+/).filter(s=>amount.test(s)||paidTerms.test(s)||hardNoFree.test(s));
  out.push({json:{Source_Kind:t.kind,Source_ID:t.id,Thread_ID:tid,Message_ID:m.id,Message_At:new Date(m.ts||Date.now()).toISOString(),Sender_Name:displayFrom(m.from)||t.outlet||'there',Sender_Email:recipient,Subject:subject,Latest_Body:m.body,Offer_Summary:clean((snippets.slice(0,3).join(' ')||m.body).slice(0,500)),Outlet:t.outlet||recipient,Track:t.track||'our music',Language:lang,Negotiation_Round:round,Existing_Error:t.error,Previous_Rounds:previousRounds,Gmail_URL:`https://mail.google.com/mail/u/0/#all/${tid}`}});
}
return out.sort((a,b)=>Date.parse(b.json.Message_At)-Date.parse(a.json.Message_At)).slice(0,5);

function clean(v){return String(v??'').trim()}
const x=$json;
const language=x.Language==='PL'?'Polish':'English';
const round=x.Negotiation_Round;
const prompt=`You write email reply drafts for VIRYA, an independent modern/alternative/progressive metal band from Wrocław, Poland.

TASK
Write a concise, personalized ${language} reply to a paid music submission/playlist/publication offer. This is negotiation, not acceptance.

CONTEXT
Contact/outlet: ${clean(x.Outlet)}
Contact name: ${clean(x.Sender_Name)}
Track/context: ${clean(x.Track)}
Original subject: ${clean(x.Subject)}
Latest paid offer: ${clean(x.Offer_Summary)}
Latest inbound email: ${clean(x.Latest_Body).slice(0,3000)}
Negotiation round: ${round}

NON-NEGOTIABLE RULES
- Never accept, promise, authorize, or imply payment.
- Never invent audience numbers, results, relationships, or prior successes.
- Do not accuse them of payola, fraud, bots, or unethical conduct.
- Be warm, direct, commercially intelligent, and 90-160 words.
- Explain briefly that VIRYA is independent and currently prioritizes editorial/organic opportunities rather than paid placement.
- Ask for ONE realistic free or reciprocal alternative tailored to their offer: editorial consideration, one short free slot, a genuine review/interview/feature, or a content exchange.
- VIRYA may offer a 15-20 second vertical video naming/tagging the outlet and directing its audience to the playlist/feature; EPK, live clip, digital assets, or a signed CD can also be offered when relevant.
- Do not offer fake streams, guaranteed engagement, reciprocal playlist manipulation, or payment later.
- Preserve a clean reply subject beginning with "Re:" only once.
- End as Wojciech / Virya.

ROUND LOGIC
${round==='FINAL' ? '- This is the final counter. Thank them for the reduced/flexible offer, clearly decline the paid option, ask once whether an occasional editorial/free slot or reciprocal content exchange exists, and if paid placement is the only route, close warmly without further bargaining.' : '- This is the first counter. Thank them for the offer and ask whether they can test one free/editorial placement or another no-budget collaboration in exchange for useful promotional content.'}

Return STRICT JSON only, without markdown:
{"subject":"...","body":"...","strategy":"...","free_alternative":"...","risk_note":"..."}`;
const payload=JSON.stringify({contents:[{role:'user',parts:[{text:prompt}]}],generationConfig:{temperature:0.45,maxOutputTokens:900,responseMimeType:'application/json'}});
return {json:{...x,payload}};

const base=$('Code — Build negotiation prompt').item.json||{};
